demo.css:
.row { display: flex; flex-wrap: wrap; gap: 14px; }
.b {
  width: 96px; height: 96px;
  display: grid; place-items: center;
  background: var(--demo-accent); color: #0b1020;
  font: 600 13px/1 var(--demo-mono);
  corner: var(--r) var(--s);
}

fallback.css:
.row { display: flex; flex-wrap: wrap; gap: 14px; }
.b {
  width: 96px; height: 96px;
  display: grid; place-items: center;
  background: var(--demo-muted); color: #0b1020;
  font: 600 13px/1 var(--demo-mono);
  border-radius: var(--r);
}
